/*!
 * SangamQR — minimal QR Code encoder for the LAN pairing screen.
 *
 * ORIGINAL implementation written for Sangam (not a copy of another
 * library). It encodes one byte-mode segment at error-correction level
 * M, versions 1–10, which covers every pairing payload (a JSON string
 * of ~90–160 characters). The algorithm follows ISO/IEC 18004; the
 * error-correction/block-count tables match the values published in
 * Nayuki's QR Code generator library (MIT licensed), which was
 * consulted as a reference for those tables only.
 *
 * QR Code is a registered trademark of DENSO WAVE INCORPORATED.
 * No new dependencies: this file is loaded at runtime by
 * js/features/settings/devices.js (see loadQrLibrary there).
 *
 * API: window.SangamQR / globalThis.SangamQR
 *   encodeText(text) -> { version, size, mask, modules }
 *     modules is an array of rows of booleans (true = dark).
 *   drawToCanvas(canvas, text, scale) -> qr object or null on failure
 */
(function (global) {
  'use strict';

  // --- Galois field GF(2^8) / 0x11D, generator 2 ---
  var EXP = new Array(512);
  var LOG = new Array(256);
  (function initGf() {
    var x = 1;
    for (var i = 0; i < 255; i++) {
      EXP[i] = x;
      LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11D;
    }
    for (var j = 255; j < 512; j++) EXP[j] = EXP[j - 255];
  })();

  function gfMul(x, y) {
    if (x === 0 || y === 0) return 0;
    return EXP[LOG[x] + LOG[y]];
  }

  function rsDivisor(degree) {
    var result = new Array(degree).fill(0);
    result[degree - 1] = 1; // start with monomial x^0
    var root = 1;
    for (var i = 0; i < degree; i++) {
      for (var j = 0; j < result.length; j++) {
        result[j] = gfMul(result[j], root);
        if (j + 1 < result.length) result[j] ^= result[j + 1];
      }
      root = gfMul(root, 0x02);
    }
    return result;
  }

  function rsRemainder(data, divisor) {
    var result = divisor.map(function () { return 0; });
    for (var k = 0; k < data.length; k++) {
      var factor = data[k] ^ result.shift();
      result.push(0);
      for (var i = 0; i < divisor.length; i++) {
        result[i] ^= gfMul(divisor[i], factor);
      }
    }
    return result;
  }

  // --- Version tables, error-correction level M (medium) ---
  // Index 0 is padding. ECC codewords per block / number of blocks.
  var ECC_PER_BLOCK = [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26];
  var NUM_BLOCKS = [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5];
  var MAX_VERSION = 10;

  function numRawDataModules(ver) {
    var result = (16 * ver + 128) * ver + 64;
    if (ver >= 2) {
      var numAlign = Math.floor(ver / 7) + 2;
      result -= (25 * numAlign - 10) * numAlign - 55;
      if (ver >= 7) result -= 36;
    }
    return result;
  }

  function numDataCodewords(ver) {
    return Math.floor(numRawDataModules(ver) / 8)
      - ECC_PER_BLOCK[ver] * NUM_BLOCKS[ver];
  }

  function alignmentPositions(ver) {
    if (ver === 1) return [];
    var numAlign = Math.floor(ver / 7) + 2;
    var step = Math.floor((ver * 8 + numAlign * 3 + 5) / (numAlign * 4 - 4)) * 2;
    var size = ver * 4 + 17;
    var result = [6];
    for (var pos = size - 7; result.length < numAlign; pos -= step) {
      result.splice(1, 0, pos);
    }
    return result;
  }

  function appendBits(val, len, out) {
    for (var i = len - 1; i >= 0; i--) out.push((val >>> i) & 1);
  }

  function getBit(x, i) {
    return ((x >>> i) & 1) !== 0;
  }

  // Remainder of x divided by a generator polynomial, for format/version bits.
  function bchRemainder(data, poly) {
    // data is shifted left so its top bit aligns with the generator's.
    var deg = 0;
    var p = poly;
    while (p > 1) { p >>= 1; deg++; }
    var rem = data;
    // Position of the highest set bit in rem, computed by shifting.
    for (var shift = 31; shift >= 0; shift--) {
      if ((rem >>> shift) & 1) {
        if (shift >= deg) rem ^= poly << (shift - deg);
        else break;
      }
    }
    return rem;
  }

  function formatBits(eclFormat, mask) {
    // eclFormat for M is 0 (see Ecc table: L=1, M=0, Q=3, H=2).
    var data = (eclFormat << 3) | mask;
    var rem = bchRemainder(data << 10, 0x537);
    return ((data << 10) | rem) ^ 0x5412;
  }

  function versionBits(ver) {
    var rem = bchRemainder(ver << 12, 0x1F25);
    return (ver << 12) | rem;
  }

  function maskBit(mask, x, y) {
    switch (mask) {
      case 0: return (x + y) % 2 === 0;
      case 1: return y % 2 === 0;
      case 2: return x % 3 === 0;
      case 3: return (x + y) % 3 === 0;
      case 4: return (Math.floor(y / 2) + Math.floor(x / 3)) % 2 === 0;
      case 5: return (x * y) % 2 + (x * y) % 3 === 0;
      case 6: return ((x * y) % 2 + (x * y) % 3) % 2 === 0;
      case 7: return ((x + y) % 2 + (x * y) % 3) % 2 === 0;
      default: throw new Error('Invalid mask');
    }
  }

  function encodeText(text) {
    var bytes;
    if (typeof TextEncoder !== 'undefined') {
      bytes = Array.from(new TextEncoder().encode(text));
    } else {
      // Fallback: encodeURIComponent trick for UTF-8 bytes.
      var enc = encodeURIComponent(text);
      bytes = [];
      for (var i = 0; i < enc.length; i++) {
        if (enc.charAt(i) === '%') { bytes.push(parseInt(enc.substr(i + 1, 2), 16)); i += 2; }
        else bytes.push(enc.charCodeAt(i));
      }
    }
    var version = -1;
    var dataCodewordsLen = 0;
    for (var ver = 1; ver <= MAX_VERSION; ver++) {
      var ccBits = ver <= 9 ? 8 : 16;
      var needed = 4 + ccBits + bytes.length * 8;
      if (needed <= numDataCodewords(ver) * 8) { version = ver; dataCodewordsLen = numDataCodewords(ver); break; }
    }
    if (version === -1) throw new Error('Text too long for a version 1-10 QR code');

    var ccBitsFinal = version <= 9 ? 8 : 16;
    var bb = [];
    appendBits(0x4, 4, bb); // byte mode
    appendBits(bytes.length, ccBitsFinal, bb);
    for (var b = 0; b < bytes.length; b++) appendBits(bytes[b], 8, bb);
    var capacityBits = dataCodewordsLen * 8;
    appendBits(0, Math.min(4, capacityBits - bb.length), bb);
    appendBits(0, (8 - (bb.length % 8)) % 8, bb);
    for (var pad = 0xEC; bb.length < capacityBits; pad ^= 0xEC ^ 0x11) appendBits(pad, 8, bb);

    var dataCodewords = [];
    for (var i = 0; i < bb.length; i += 8) {
      var cw = 0;
      for (var j = 0; j < 8; j++) cw = (cw << 1) | bb[i + j];
      dataCodewords.push(cw);
    }

    // Split into blocks, compute ECC, interleave (spec order: all data
    // bytes column-wise, then all ECC bytes column-wise).
    var numBlocks = NUM_BLOCKS[version];
    var eccLen = ECC_PER_BLOCK[version];
    var divisor = rsDivisor(eccLen);
    var shortDataLen = Math.floor(dataCodewordsLen / numBlocks);
    var numShort = numBlocks - (dataCodewordsLen % numBlocks);
    var blocksData = [];
    var blocksEcc = [];
    var k = 0;
    for (var bi = 0; bi < numBlocks; bi++) {
      var len = shortDataLen + (bi < numShort ? 0 : 1);
      var dat = dataCodewords.slice(k, k + len);
      k += len;
      blocksData.push(dat);
      blocksEcc.push(rsRemainder(dat, divisor));
    }
    var allCodewords = [];
    var maxDataLen = shortDataLen + (numShort < numBlocks ? 1 : 0);
    for (var di = 0; di < maxDataLen; di++) {
      for (var bj = 0; bj < numBlocks; bj++) {
        if (di < blocksData[bj].length) allCodewords.push(blocksData[bj][di]);
      }
    }
    for (var ei = 0; ei < eccLen; ei++) {
      for (var bj2 = 0; bj2 < numBlocks; bj2++) allCodewords.push(blocksEcc[bj2][ei]);
    }

    // Build the symbol, trying every mask and keeping the lowest penalty.
    var best = null;
    for (var mask = 0; mask < 8; mask++) {
      var qr = buildSymbol(version, allCodewords, mask);
      var penalty = penaltyScore(qr.modules, qr.size);
      if (best === null || penalty < best.penalty) best = { penalty: penalty, qr: qr };
    }
    return best.qr;
  }

  function buildSymbol(version, allCodewords, mask) {
    var size = version * 4 + 17;
    var modules = [];
    var isFunction = [];
    for (var y = 0; y < size; y++) {
      modules.push(new Array(size).fill(false));
      isFunction.push(new Array(size).fill(false));
    }

    function setFn(x, y, dark) {
      modules[y][x] = dark;
      isFunction[y][x] = true;
    }

    // Timing patterns.
    for (var i = 0; i < size; i++) {
      setFn(6, i, i % 2 === 0);
      setFn(i, 6, i % 2 === 0);
    }
    // Finder patterns (+ separators) in three corners.
    function finder(cx, cy) {
      for (var dy = -4; dy <= 4; dy++) {
        for (var dx = -4; dx <= 4; dx++) {
          var dist = Math.max(Math.abs(dx), Math.abs(dy));
          var xx = cx + dx, yy = cy + dy;
          if (0 <= xx && xx < size && 0 <= yy && yy < size) setFn(xx, yy, dist !== 2 && dist !== 4);
        }
      }
    }
    finder(3, 3);
    finder(size - 4, 3);
    finder(3, size - 4);
    // Alignment patterns.
    var alignPos = alignmentPositions(version);
    for (var ai = 0; ai < alignPos.length; ai++) {
      for (var aj = 0; aj < alignPos.length; aj++) {
        var ax = alignPos[ai], ay = alignPos[aj];
        var isCorner = (ax === 6 && ay === 6) || (ax === 6 && ay === size - 7) || (ax === size - 7 && ay === 6);
        if (isCorner) continue;
        for (var dy2 = -2; dy2 <= 2; dy2++) {
          for (var dx2 = -2; dx2 <= 2; dx2++) {
            setFn(ax + dx2, ay + dy2, Math.max(Math.abs(dx2), Math.abs(dy2)) !== 1);
          }
        }
      }
    }
    // Format bits (ECL M format value is 0).
    var fmt = formatBits(0, mask);
    for (var fi = 0; fi <= 5; fi++) setFn(8, fi, getBit(fmt, fi));
    setFn(8, 7, getBit(fmt, 6));
    setFn(8, 8, getBit(fmt, 7));
    setFn(7, 8, getBit(fmt, 8));
    for (var fi2 = 9; fi2 < 15; fi2++) setFn(14 - fi2, 8, getBit(fmt, fi2));
    for (var fi3 = 0; fi3 < 8; fi3++) setFn(size - 1 - fi3, 8, getBit(fmt, fi3));
    for (var fi4 = 8; fi4 < 15; fi4++) setFn(8, size - 15 + fi4, getBit(fmt, fi4));
    setFn(size - 8, 8, true); // dark module
    // Version info (versions 7+).
    if (version >= 7) {
      var vb = versionBits(version);
      for (var vi = 0; vi < 18; vi++) {
        var bit = getBit(vb, vi);
        var a = size - 11 + (vi % 3);
        var bb2 = Math.floor(vi / 3);
        setFn(a, bb2, bit);
        setFn(bb2, a, bit);
      }
    }
    // Data codewords, zigzag from the bottom right, skipping column 6.
    var bitIdx = 0;
    var totalBits = allCodewords.length * 8;
    for (var right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (var vert = 0; vert < size; vert++) {
        for (var jj = 0; jj < 2; jj++) {
          var x = right - jj;
          var upward = ((right + 1) & 2) === 0;
          var yy2 = upward ? size - 1 - vert : vert;
          if (!isFunction[yy2][x] && bitIdx < totalBits) {
            modules[yy2][x] = getBit(allCodewords[bitIdx >>> 3], 7 - (bitIdx & 7));
            bitIdx++;
          }
        }
      }
    }
    // Mask (data modules only).
    for (var my = 0; my < size; my++) {
      for (var mx = 0; mx < size; mx++) {
        if (!isFunction[my][mx] && maskBit(mask, mx, my)) modules[my][mx] = !modules[my][mx];
      }
    }
    return { version: version, size: size, mask: mask, modules: modules };
  }

  function penaltyScore(modules, size) {
    var PEN_N1 = 3, PEN_N2 = 3, PEN_N3 = 40, PEN_N4 = 10;
    var score = 0;
    // N1: runs of 5+ same-colour modules in rows and columns.
    function runPenalty(line) {
      var pen = 0, runColor = line[0], runLen = 1;
      for (var i = 1; i < line.length; i++) {
        if (line[i] === runColor) runLen++;
        else {
          if (runLen >= 5) pen += PEN_N1 + (runLen - 5);
          runColor = line[i]; runLen = 1;
        }
      }
      if (runLen >= 5) pen += PEN_N1 + (runLen - 5);
      return pen;
    }
    for (var y = 0; y < size; y++) score += runPenalty(modules[y]);
    for (var x = 0; x < size; x++) {
      var col = [];
      for (var yy = 0; yy < size; yy++) col.push(modules[yy][x]);
      score += runPenalty(col);
    }
    // N2: 2x2 blocks of one colour.
    for (var y2 = 0; y2 < size - 1; y2++) {
      for (var x2 = 0; x2 < size - 1; x2++) {
        var c = modules[y2][x2];
        if (c === modules[y2][x2 + 1] && c === modules[y2 + 1][x2] && c === modules[y2 + 1][x2 + 1]) score += PEN_N2;
      }
    }
    // N3: finder-like patterns 10111010000 / 00001011101.
    function finderPenalty(line) {
      var pen = 0;
      var bits = line.map(function (b) { return b ? '1' : '0'; }).join('');
      for (var i = 0; i + 11 <= bits.length; i++) {
        var w = bits.substr(i, 11);
        if (w === '10111010000' || w === '00001011101') pen += PEN_N3;
      }
      return pen;
    }
    for (var y3 = 0; y3 < size; y3++) score += finderPenalty(modules[y3]);
    for (var x3 = 0; x3 < size; x3++) {
      var col3 = [];
      for (var yy3 = 0; yy3 < size; yy3++) col3.push(modules[yy3][x3]);
      score += finderPenalty(col3);
    }
    // N4: dark-module proportion vs 50%, in 5% steps.
    var dark = 0;
    for (var y4 = 0; y4 < size; y4++) for (var x4 = 0; x4 < size; x4++) if (modules[y4][x4]) dark++;
    var total = size * size;
    var k = Math.floor(Math.abs(dark * 20 - total * 10) / total);
    score += k * PEN_N4;
    return score;
  }

  function drawToCanvas(canvas, text, scale) {
    var qr;
    try {
      qr = encodeText(text);
    } catch (e) {
      return null;
    }
    var border = 4;
    var px = scale || 4;
    var dim = (qr.size + border * 2) * px;
    canvas.width = dim;
    canvas.height = dim;
    var ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, dim, dim);
    ctx.fillStyle = '#000000';
    for (var y = 0; y < qr.size; y++) {
      for (var x = 0; x < qr.size; x++) {
        if (qr.modules[y][x]) ctx.fillRect((x + border) * px, (y + border) * px, px, px);
      }
    }
    return qr;
  }

  var api = { encodeText: encodeText, drawToCanvas: drawToCanvas };
  global.SangamQR = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(typeof window !== 'undefined' ? window : globalThis);
